template<class S>bool same_precision(const S& a,const S& b){bool same=bits(a.time_tolerance)==bits(b.time_tolerance)&&a.max_evaluations==b.max_evaluations&&a.max_leaves==b.max_leaves&&a.max_depth==b.max_depth;if constexpr(requires{a.sqrt_refinements;}){same=same&&a.sqrt_refinements==b.sqrt_refinements;}return same;}
const f::Case& named(const std::vector<f::Case>& corpus,std::string_view name){const auto it=std::find_if(corpus.begin(),corpus.end(),[&](const auto& x){return x.name==name;});require(it!=corpus.end(),"Missing original case: "+std::string(name));return *it;}
g::GuardResult query(const f::Case& x){return g::query(x.world,x.meshes,x.horizon,x.settings);}
template<class F>void calls(const g::GuardResult& r,F visit){for(const auto& pair:r.pairs){std::visit([&](const auto& child){using C=std::remove_cvref_t<decltype(child)>;if constexpr(std::is_same_v<C,g::PlaneCalls>){visit(child.metric);visit(child.box);}else{visit(child);}},pair.child);}}
