void reservation(const g::GuardResult& r){g::Retained kept{};g::WorkGrant issued{};if(r.initial_request&&r.reservation.retained.logical_payload_bytes){kept=*r.initial_request;}calls(r,[&](const auto& call){if(!call.granted){require(call.state==g::CallState::unexamined&&!call.attempt_ordinal&&!call.result,"Refused request cannot fabricate call/result");return;}for(auto member:retained_fields()){kept.*member+=call.grant.retained.*member;}for(auto member:work_fields()){issued.*member+=call.grant.work.*member;}});for(auto member:retained_fields()){require(kept.*member==r.reservation.retained.*member,"Requested retained capacity accumulates without actual-size refund");}for(auto member:work_fields()){require(issued.*member==r.reservation.granted.*member,"All original issued work grants accumulated");}if(!r.original_settings){return;}const auto& l=r.original_settings->limits;const auto& v=r.reservation.retained;require(v.body_records<=l.body_records&&v.pair_records<=l.pair_records&&v.held_audits<=l.held_audits&&v.held_certified_leaves<=l.held_certified_leaves&&v.held_partition<=l.held_partition&&v.held_frontier<=l.held_frontier&&v.primitive_audits<=l.primitive_audits&&v.primitive_partition<=l.primitive_partition&&v.primitive_frontier<=l.primitive_frontier&&v.last_mesh_rows<=l.last_mesh_rows&&v.primitive_candidates<=l.primitive_candidates&&v.retained_faces<=l.retained_faces&&v.logical_payload_bytes<=l.logical_payload_bytes,"All charged retained capacities within limits");const auto& w=r.reservation.charged;require(w.mesh_queries<=l.mesh_queries&&w.primitive_queries<=l.primitive_queries&&w.candidates_examined<=l.candidates_examined&&w.sqrt_refinements<=l.sqrt_refinements&&w.propagations<=l.propagations&&w.plane_metric_values<=l.plane_metric_values&&w.box_values<=l.box_values,"Settled upper work respects limits");}
