Observed check_case(const f::Case& x){const auto original=input_text(x),world=world_text(x.world);std::vector<const d::RigidBody*> pointers;for(const auto& body:x.world.bodies()){pointers.push_back(&body);}const auto r=query(x);require(input_text(x)==original&&world_text(x.world)==world,"Original World/source/gravity/loads/settings all bits unchanged");for(std::size_t i=0;i<pointers.size();++i){require(pointers[i]==&x.world.bodies()[i],"All original World body pointers stable");}if(x.expected){require(r.status==*x.expected,x.name+": expected status");}if(x.reason){require(r.reason==*x.reason,x.name+": expected reason");}return full_provenance(x,r);}
void minimal_and_grants(const std::vector<f::Case>& corpus){const auto r=query(named(corpus,"minimal-two-dynamic-two-mesh-one-plane"));require(r.status==g::Status::certified_separated&&r.pairs.size()==7&&r.bodies.size()==2&&r.work.child_calls_attempted==9&&r.work.mesh_calls_attempted==4&&r.work.plane_metric_calls_attempted==2&&r.work.plane_box_calls_attempted==2&&r.work.sphere_box_calls_attempted==1,"Nonvacuous seven required pairs/nine actual calls");require(r.work.propagation_attempts.known==4&&r.work.bridge_calls_upper==4,"Repeated mesh propagations counted, no fictional seed reuse");require(r.reservation.retained.held_audits==1024&&r.reservation.retained.primitive_audits==1024,"Small actual size never refunds held/primitive capacity");std::vector<std::pair<std::size_t,std::size_t>> grants;calls(r,[&](const auto& call){using C=std::remove_cvref_t<decltype(call)>;if constexpr(!std::is_same_v<C,g::MeshCall>){require(call.attempt_ordinal.has_value(),"Real primitive execution ordinal");grants.push_back({*call.attempt_ordinal,call.used_settings.max_evaluations});}});std::sort(grants.begin(),grants.end());require(grants.size()==5,"Exactly five primitive grants");for(std::size_t i=0;i<5;++i){require(grants[i].second==(i==4?4U:255U),"Four times255 retained then final visible grant4");}
    const std::array<std::pair<const char*,std::size_t>,2> partial{{{"primitive-retained-audits-1023-last-grant3",3},{"primitive-retained-audits-1021-last-grant1",1}}};for(const auto& [name,E]:partial){const auto small=query(named(corpus,name));require(small.status==g::Status::certified_separated,"Far safe closed root can certify with reduced final E");std::size_t last=0,last_E=0;calls(small,[&](const auto& call){using C=std::remove_cvref_t<decltype(call)>;if constexpr(!std::is_same_v<C,g::MeshCall>){if(call.attempt_ordinal&&*call.attempt_ordinal>=last){last=*call.attempt_ordinal;last_E=call.used_settings.max_evaluations;}}});require(last_E==E,"Exact source-visible partial primitive grant");}const auto stop=query(named(corpus,"primitive-retained-audits-1020-last-unqueried"));require(!stop.candidate_bodies&&stop.pairs.size()==7&&stop.work.child_calls_attempted==8,"Zero last grant leaves pair/fulltail unqueried");}
void dependencies_and_capacity(const std::vector<f::Case>& corpus){const auto failed=query(named(corpus,"failed-seed-first-body-dependency-records"));require(failed.pairs.size()==7&&!failed.candidate_bodies,"Seed failure retains all pair keys");require(std::count_if(failed.bodies.begin(),failed.bodies.end(),[](const auto& b){return b.state==g::SeedState::failed;})==1&&std::count_if(failed.bodies.begin(),failed.bodies.end(),[](const auto& b){return b.state==g::SeedState::ready;})==1,"Failed seed preserves other independent ready seed");require(std::count_if(failed.pairs.begin(),failed.pairs.end(),[](const auto& pair){return pair.state==g::PairState::dependency_failed;})==2,"Failed first seed blocks its plane and sphere dependencies");const auto full=query(named(corpus,"full-8-16-4-64-whole188-pair-tail"));require(full.preparation&&full.preparation->inventory&&full.preparation->inventory->pairs.size()==188&&full.preparation->inventory->excluded.total==190&&full.preparation->inventory->all_pairs==378,"All188 required plus190 excluded of378 collider pairs");require(full.pairs.size()==188&&full.bodies.size()==8&&!full.candidate_bodies&&std::any_of(full.pairs.begin(),full.pairs.end(),[](const auto& pair){return pair.state==g::PairState::unexamined;}),"Full-capacity budget stop retains complete unexamined tail");const auto vacuous=query(named(corpus,"full-all-static378-excluded"));require(vacuous.status==g::Status::certified_separated&&vacuous.pairs.empty()&&vacuous.candidate_bodies&&vacuous.candidate_bodies->size()==8&&vacuous.work.child_calls_attempted==0&&vacuous.preparation->inventory->excluded.total==378,"Static overlap exclusion is vacuous dynamic flight, not static contact proof");}
