int main(int argc,char** argv){try{if(argc==2&&std::string_view(argv[1])=="--unsupported-profile"){unsupported_profile();std::cout<<"World static mesh flight guard: unsupported build profile refusal PASS; child calls0; no actual bound World certificate.\n";return 0;}require(g::current_binding().state==g::BindingState::ready,"Nonvacuity requires externally audited actual build; use --unsupported-profile separately");const auto corpus=f::cases();if(argc==2&&std::string_view(argv[1])=="--fixtures"){f::emit_fixtures(std::cout,corpus);return 0;}if(argc==2&&std::string_view(argv[1])=="--storage"){storage(corpus);return 0;}require(argc==1||(argc==2&&std::string_view(argv[1])=="--run"),"Usage: tests [--run|--fixtures|--storage|--unsupported-profile]");std::set<std::string> names;Observed total;for(const auto& x:corpus){require(names.insert(x.name).second,"Unique original input labels");const auto count=check_case(x);total.child+=count.child;total.provenance+=count.provenance;}minimal_and_grants(corpus);dependencies_and_capacity(corpus);preserved49_and_explicit_controls(corpus);source_order(corpus);ownership();settings_boundaries();environment();std::cout<<"World static mesh flight guard: "<<corpus.size()+7<<" groups PASS; "<<corpus.size()<<" finite fixtures; "<<total.child<<" actual child calls / "<<total.provenance<<" whole child DTO direct-repeat comparisons. Independent math and actual linked binding acceptance separate; no natural allocator/nonreturn fault injection, World advance or response.\n";return 0;}catch(const std::exception& e){std::cerr<<"World static mesh flight guard FAIL: "<<e.what()<<'\n';return 1;}}
